    if plan.token_aligner_plan is not None:
        combined: Pair[torch.Tensor] = execute_token_aligner(
            plan=plan.token_aligner_plan,
            tensor_of_step_pair=Pair(x=step_tensors_x, y=step_tensors_y),
            token_dims=plan.token_dims,
